mapper.select:
SELECT tpd.TRADE_ID AS tradeId, -- 交易编号 bda.BOOKSET_ID AS bookSetId, -- 账套代码 bb.BOOKSET_NAME AS bookSetName, -- 账套名称 DATE_FORMAT(tpd.TRADE_DATE, '%Y-%m-%d') AS payDate, -- 交易日 支付日 DATE_FORMAT(tpd.MDATE, '%Y-%m-%d') AS mDate, -- 到期日 tpd.CCY AS ccy, -- 交易币种 trfd.FEE_TYPE AS feeType, -- 费用类型 trfd.FEE_AMT AS feeAmt, -- 费用金额 tpd.REGIST_ORG AS registOrg, -- 登记托管机构 trfd.IS_PREPAID AS isPrepaid -- 是否待摊 FROM BOK_DEAL_ACCOUNTING bda INNER JOIN TRD_PRODUCT_DEAL tpd ON bda.BUSI_NO = tpd.TRADE_ID AND tpd.TRADE_STATUS != #{tradeStatus0,jdbcType=VARCHAR} AND tpd.PS = #{ps0,jdbcType=VARCHAR} LEFT JOIN TRD_PRODUCT_DEAL tpd2 ON tpd.TRADE_ID = tpd2.P_TRADE_ID AND tpd2.TRADE_STATUS = #{tradeStatus0,jdbcType=VARCHAR} INNER JOIN TRD_TRADE_FEE_DETAIL trfd ON trfd.TRADE_ID = tpd.TRADE_ID -- 一次性费用 佣金 账户维护费 其他费用 交易手续费 结算手续费 AND trfd.FEE_TYPE IN
#{ele}
INNER JOIN BOK_BOOKSET bb ON bb.BOOKSET_ID = bda.BOOKSET_ID
tpd2.TRADE_ID is null
AND bda.BOOKSET_ID = #{bookSetId,jdbcType=VARCHAR}
AND tpd2.TRADE_DATE = STR_TO_DATE(#{tradeDate},'%Y-%m-%d')
AND trfd.FEE_TYPE IN
#{item}
ORDER BY bda.BOOKSET_ID, tpd.TRADE_DATE DESC
